    function changeLabel(change){if(change.path==='markets.COUPANG.overrides.productName')return '노출상품명';if(change.path==='productQuantity')return '상품 공통 재고수량';if(change.path.startsWith('common.'))return commonSpec[change.path.slice(7)]?.[0]||change.path;const option=reference.options.find(o=>o.id===change.optionId)?.name||'옵션';return change.path.startsWith('options.')?option+' · '+({name:'옵션명',sku:'판매자 상품코드',price:'판매가',quantity:'판매 수량'})[change.path.slice(8)]:change.path.startsWith('media.')?(change.optionId?option+' · ':'공통 · ')+(change.path==='media.images'?'이미지':'설명'):change.path.startsWith('delivery.')?deliverySpec[change.path.slice(9)]?.[0]||change.path:change.path.includes('attributes')?'속성':change.path.includes('notices')?'상품고시':change.path.includes('registration')?'옵션 등록 설정':change.path.includes('settings')?'상품 설정':change.path;}
