    function renderApply(){const host=$('common-apply-panel');host.hidden=!!viewMarket||!editState;if(host.hidden)return;const changes=[{path:'markets.COUPANG.overrides.productName',optionId:null},...['name','productName','brand','manufacturer','origin','material','model','afterService','taxType','adultOnly'].map(k=>({path:'common.'+k,optionId:null})),...reference.options.flatMap(o=>['name','sku','price',...(reference.stockMode==='OPTION'?['quantity']:[])].map(k=>({path:'options.'+k,optionId:o.id}))),...(reference.stockMode==='PRODUCT'?[{path:'productQuantity',optionId:null}]:[]),...M.deliveryKeys.map(k=>({path:'delivery.'+k,optionId:null})),...[null,...reference.options.map(o=>o.id)].flatMap(optionId=>[{path:'media.images',optionId},{path:'media.contents',optionId}])];$('common-apply-fields').innerHTML=changes.map(c=>`<label><input type="checkbox" data-apply-path="${e(c.path)}" ${c.path.startsWith('media.')&&!c.optionId?'disabled title="이미지·설명은 옵션별로 적용해 주세요."':['common.brand','common.origin','common.material','common.afterService','stockMode','productQuantity'].includes(c.path)&&[...editState.targets.values()].filter(t=>t.status==='READY').every(t=>t.mode==='UPDATE')?'disabled':''} ${c.optionId?`data-apply-option="${e(c.optionId)}"`:''}><span>${e(changeLabel(c))}</span></label>`).join('');$('common-apply-targets').innerHTML=[...editState.targets.values()].map(t=>`<label class="common-inline-label"><input type="checkbox" data-apply-target="${e(t.market)}" ${t.status!=='READY'?'disabled':''}>${e(marketName(t.market))}</label>`).join('');}
