    function chooseView(market){viewMarket=market||null;selectedMarket=viewMarket||'COUPANG';draft=viewMarket&&activeTarget()?.status!=='UNSUPPORTED'?activeTarget()?.working||M.fresh(viewMarket):reference;selectedMarketOption=draft.options[0]?.id;selectedMedia=viewMarket&&activeTarget()?.status==='READY'?draft.options[0]?.id??null:null;render();}
    function installSession(session,preserve=true){clearTimeout(expiryTimer);const remaining=Date.parse(session.expiresAt)-Date.now();expiryTimer=setTimeout(()=>{renderLiveState();submissions.update();},Math.max(0,Math.min(remaining,2147483647)));editState=M.sessionState(reference,session,preserve?editState:null);if(viewMarket&&!editState.targets.has(viewMarket))viewMarket=null;chooseView(viewMarket);}
    async function startSession(){if(!reference?.id)return;const seq=sequence,read=window.CoupangRead.start('/api/marketplaces/drafts/'+encodeURIComponent(reference.id)+'/edit-sessions',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});sessionRead=read;try{const session=await read.promise;if(seq!==sequence)return;installSession(session);}finally{if(sessionRead===read)sessionRead=null;}}
    async function refreshTarget(){if(busy||loading||uploads.size||!reference?.id)return;if(dirty&&!window.confirm('현재 입력을 유지하면서 마켓의 최신값을 다시 조회할까요?'))return;const market=viewMarket,seq=sequence;loading=true;renderLiveState();submissions.changed();try{if(expired()||!editState)await startSession();else {sessionRead=window.CoupangRead.start('/api/marketplaces/edit-sessions/'+encodeURIComponent(editState.session.id)+'/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({market})});const session=await sessionRead.promise;if(seq!==sequence)return;installSession(session);}if(seq!==sequence)return;dirty=referenceDirty||[...editState.targets.values()].some(t=>t.changes.size);}catch(err){if(seq!==sequence)return;const target=editState?.targets.get(market);if(target){target.refreshError=err.message;target.status='FAILED';}else {$('common-error').textContent=err.message;$('common-error').hidden=false;}}finally{if(seq===sequence){loading=false;sessionRead=null;chooseView(viewMarket);submissions.update();}}}
    async function category(){
        if(viewMarket==='COUPANG'&&activeTarget()?.mode==='UPDATE')return;
        if(categoryRead)return;
        const code=draft.markets.COUPANG.categoryCode;if(!/^\d+$/.test(code)){ruleErrors.set('COUPANG','카테고리 코드를 숫자로 입력해 주세요.');renderBasic();renderMedia();renderMarkets();renderDelivery();markLocks();return;}
        const seq=++categorySequence;ruleErrors.set('COUPANG','카테고리 규격 조회 중…');renderBasic();renderMedia();renderMarkets();renderDelivery();markLocks();
        try{categoryRead=window.CoupangRead.start('/api/marketplaces/coupang/categories/'+encodeURIComponent(code)+'/rules');updateBusy();const r=await categoryRead.promise;if(seq!==categorySequence||code!==draft.markets.COUPANG.categoryCode)return;if(r.categoryCode!==code)throw Error('카테고리 규격 응답을 확인해 주세요.');rules.set('COUPANG',r);ruleErrors.delete('COUPANG');const c=ensureCoupang();for(const o of c.options){for(const a of r.attributes||[])if(!(c.sellerProductId&&a.exposed==='EXPOSED')&&!o.attributes.some(v=>v.name===a.name))o.attributes.push({name:a.name,value:draft.options.find(v=>v.id===o.optionId)?.attributes.find(v=>v.name===a.name)?.value||'',exposed:a.exposed});const notice=r.notices?.find(v=>v.name===o.notices[0]?.category)||r.notices?.[0];o.notices=(notice?.fields||[]).map(f=>({category:notice.name,name:f.name,content:o.notices.find(v=>v.category===notice.name&&v.name===f.name)?.content??({'소재':draft.common.material,'제조국':draft.common.origin,'A/S 책임자와 전화번호':draft.common.afterService})[f.name]??''}));for(const cert of r.certifications||[])if(cert.required==='MANDATORY'&&!o.certifications.some(v=>v.type===cert.type))o.certifications.push({type:cert.type,code:'',attachments:[]});}for(const d of r.documents||[])if(d.required==='MANDATORY'&&!c.documents.some(v=>v.templateName===d.name))c.documents.push({templateName:d.name,path:''});for(let n=0;n<c.options.length;n++)for(const key of ['attributes','notices','certifications','registration'])changed('markets.COUPANG.coupang.options.'+n+'.'+key);changed('markets.COUPANG.coupang.documents');renderBasic();renderMedia();renderMarkets();renderDelivery();markLocks();}catch(err){if(seq===categorySequence){ruleErrors.set('COUPANG',err.message);renderBasic();renderMedia();renderMarkets();renderDelivery();markLocks();}}finally{if(seq===categorySequence){categoryRead=null;updateBusy();}}
    }
    async function initialize(){if(loading)return;loading=true;$('common-loading').hidden=false;$('common-error').hidden=true;$('common-retry').hidden=true;const seq=++sequence;try{reference=edit?M.normalize(await apiGet('/api/marketplaces/drafts/'+encodeURIComponent(edit[1]))):M.fresh(new URLSearchParams(location.search).get('market')||'COUPANG');if(seq!==sequence)return;draft=reference;if(reference.id)await startSession();if(seq!==sequence)return;dirty=false;referenceDirty=false;chooseView(null);}catch(err){if(seq===sequence){$('common-error').textContent=err.message;$('common-error').hidden=false;$('common-retry').hidden=false;if(reference){draft=reference;viewMarket=null;render();}}}finally{if(seq===sequence){loading=false;$('common-loading').hidden=true;if(draft)updateBusy();else submissions.update();}}}
    function validationSummary(result){return `<div class="common-validation-markets">${draft.selectedMarkets.map(m=>{const errors=(result.errors||[]).some(v=>!v.market||v.market===m),unverified=(result.unverified||[]).some(v=>!v.market||v.market===m),state=errors?'오류':unverified?'규격 확인 필요':result.valid?'검증 완료':'문서 검증',style=errors?'fail':unverified?'pending':'ok';return `<span class="badge ${style}">${e(marketName(m)+' · '+state)}</span>`;}).join('')}</div>`;}
    function showResult(result,saved=false){const box=$('common-validation'),errors=result.errors||[],unverified=result.unverified||[];box.hidden=false;box.className='editor-validation '+(errors.length?'form-error':result.valid||saved?'editor-validation-success':'editor-validation-pending');box.innerHTML=`<strong>${saved?'임시 저장 완료':result.valid?'입력 검증 완료':'입력 확인 결과'}</strong>${saved?'':validationSummary(result)}${errors.length?`<ul class="common-validation-list">${errors.map((issue,n)=>`<li><button type="button" class="marketplace-product-link" data-issue="${n}">${e((issue.market?marketName(issue.market)+' · ':'')+issue.message)}</button></li>`).join('')}</ul>`:''}${unverified.length?`<ul class="common-validation-list">${unverified.map(v=>`<li>${e((v.market?marketName(v.market)+' · ':'')+v.message)}</li>`).join('')}</ul>`:''}`;box.querySelectorAll('[data-issue]').forEach(button=>button.addEventListener('click',()=>focusIssue(errors[Number(button.dataset.issue)])));if(errors.length)focusIssue(errors[0]);else box.focus();}
    function focusIssue(issue){if(issue.market&&draft.markets[issue.market]){selectedMarket=issue.market;renderMarkets();$('common-markets').scrollIntoView({block:'start'});}else {const section=issue.path?.startsWith('media')?'common-media':issue.path?.startsWith('delivery')?'common-delivery':issue.path?.startsWith('markets')?'common-markets':'common-basic';$(section).scrollIntoView({block:'start'});}const path=(issue.path||'').replace(/\[(\d+)\]/g,'.$1'),control=document.querySelector('[data-common-field="'+CSS.escape(path)+'"]');if(control&&!control.disabled){control.setAttribute('aria-invalid','true');control.focus({preventScroll:true});}}
    async function validate(){if(busy||uploads.size||categoryRead||!draft)return;const target=activeTarget();if(target?.status==='READY'&&target.mode==='UPDATE'){const errors=M.validateChanges(target);showResult({valid:!errors.length,errors,unverified:[]});return;}const document=target?.status==='READY'?target.working:reference;const errors=[...M.validate(document,true),...brandErrors(document)];if(errors.length){showResult({valid:false,errors,unverified:[]});return;}busy=true;updateBusy();$('common-error').hidden=true;try{validationRead=window.CoupangRead.start('/api/marketplaces/drafts/validate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(document)});showResult(await validationRead.promise);}catch(err){$('common-error').textContent=err.message;$('common-error').hidden=false;}finally{validationRead=null;busy=false;updateBusy();}}
    async function save(quiet=false){if(busy||uploads.size||categoryRead||!reference)return null;if(quiet&&reference.id&&!referenceDirty&&editState)return reference;const errors=[...M.validate(reference),...brandErrors(reference)];if(errors.length){showResult({valid:false,errors,unverified:[]});return;}busy=true;updateBusy();$('common-error').hidden=true;try{if(editState&&!expired()){const session=await apiRequest('/api/marketplaces/edit-sessions/'+encodeURIComponent(editState.session.id)+'/reference',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(reference)});reference.revision=session.revision;installSession(session);}else {const saved=reference.id?await apiRequest('/api/marketplaces/drafts/'+encodeURIComponent(reference.id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(reference)}):await apiPost('/api/marketplaces/drafts',reference);reference=M.normalize(saved);await startSession();}referenceDirty=false;dirty=[...editState.targets.values()].some(t=>t.changes.size);history.replaceState(null,'','/marketplaces/products/'+encodeURIComponent(reference.id)+'/edit');chooseView(viewMarket);if(!quiet)showResult({valid:false,errors:[],unverified:[]},true);return reference;}catch(err){$('common-error').textContent=err.status===409?'다른 작업에서 공통 정보가 변경되었습니다. 현재 입력은 유지됩니다.':err.message;$('common-error').hidden=false;return null;}finally{busy=false;updateBusy();}}
    async function files(list){const optionId=selectedMedia;let error='';for(const file of Array.from(list||[])){if(!['image/jpeg','image/png'].includes(file.type)||file.size>10*1024*1024){error='10MiB 이하 JPG·PNG 파일을 선택해 주세요.';continue;}const pending={};uploads.add(pending);updateBusy();$('common-upload-state').textContent='이미지 업로드 중…';try{const form=new FormData();form.append('file',file);const asset=await apiRequest('/api/marketplaces/assets',{method:'POST',body:form});if(!asset?.id||!asset.url)throw Error('업로드 응답을 확인해 주세요.');if(optionId&&!draft.options.some(o=>o.id===optionId))throw Error('이미지의 옵션이 삭제되었습니다. 공통 또는 남은 옵션에서 다시 업로드해 주세요.');const imgs=M.imagesFor(draft,optionId);draft.media.images.push({id:M.uuid(),assetId:asset.id,url:asset.url,representative:!imgs.length&&!(viewMarket==='COUPANG'&&M.imagesFor(draft,null).some(i=>i.representative)),order:imgs.length,optionId});mediaChanged('images',optionId);}catch(err){error=err.message;}finally{uploads.delete(pending);renderMedia();updateBusy();}}if(error){$('common-image-error').textContent=error;$('common-image-error').hidden=false;}}
    function input(control){if(busy||control.disabled)return;const path=control.dataset.commonField;if(!path)return;const previous=control.dataset.arrayPath?get(control.dataset.arrayPath)?.find(row=>row.name===control.dataset.arrayKey)?.value:get(path),next=path.endsWith('.choices')?control.value.split(',').map(v=>v.trim()).filter(Boolean):control.value;if(M.equal(previous,next,path))return;let changedPath=path;if(control.dataset.arrayPath){const rows=get(control.dataset.arrayPath),key=control.dataset.arrayKey;let row=rows.find(v=>v.name===key);if(!row){row={name:key,value:''};rows.push(row);}row.value=control.value;changedPath=control.dataset.arrayPath;}else set(path,path.endsWith('.choices')?control.value.split(',').map(v=>v.trim()).filter(Boolean):control.value);if(!viewMarket&&path==='common.brand'&&draft.markets.COUPANG.coupang&&!draft.markets.COUPANG.coupang.sellerProductId){draft.markets.COUPANG.coupang.settings=draft.markets.COUPANG.coupang.settings.filter(v=>v.name!=='brandId');const identifier=control.closest('.coupang-brand-field')?.querySelector('[aria-label="쿠팡 브랜드 ID"]');if(identifier)identifier.value='';}changed(changedPath);if(path==='markets.COUPANG.categoryCode'){categorySequence++;categoryRead?.cancel();categoryRead=null;rules.delete('COUPANG');ruleErrors.delete('COUPANG');updateBusy();}if(viewMarket==='COUPANG'&&path.includes('.attributes.')&&path.endsWith('.value'))updateCoupangCombinations();if(path.startsWith('media.contents.'))previews();for(const other of document.querySelectorAll('[data-common-field]'))if(other!==control&&other.dataset.commonField===path)other.value=control.value;if(viewMarket==='COUPANG'&&control.dataset.arrayKey==='searchTags')renderCoupangTags(control.value);if(path==='common.brand')document.querySelectorAll('[data-coupang-brand]').forEach(el=>el.textContent=control.value||'미입력');if(path==='stockMode'){renderBasic();renderMarkets();markLocks();}}
